tool_and_message_events.command:
/bin/bash -lc 'set -eu
review_dir=$(mktemp -d ./.catalog-review.XXXXXXXX)
cleanup() {
  for name in pin unpin missing; do
    if [ -f "$review_dir/$name.json" ]; then unlink "$review_dir/$name.json"; fi
  done
  rmdir "$review_dir"
}
trap cleanup EXIT
node --input-type=module - "$review_dir" <<'"'NODE'
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const root = process.argv[2];
const fixture = JSON.parse(readFileSync('catalog/fixture/catalog.json', 'utf8'));
const records = [...fixture, { id: 'c', title: 'Other pinned', pinned: true }, { id: 'd', title: 'Legacy' }];
for (const name of ['pin', 'unpin', 'missing']) {
  writeFileSync(join(root, name + '.json'), JSON.stringify(records));
}
NODE
node --input-type=module - \""'$review_dir" <<'"'NODE'
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';
const root = process.argv[2];
for (const [scenario, id, value] of [['pin', 'a', true], ['unpin', 'b', false]]) {
  const path = join(root, scenario + '.json');
  const initial = loadCatalog(path);
  const changed = setPinned(initial, id, value);
  saveCatalog(path, changed);
  console.log(JSON.stringify({ scenario, initial, changed, stored: JSON.parse(readFileSync(path, 'utf8')) }));
}
const path = join(root, 'missing.json');
const before = readFileSync(path, 'utf8');
let error;
try {
  const changed = setPinned(loadCatalog(path), 'missing', true);
  saveCatalog(path, changed);
} catch (caught) {
  error = caught.message;
}
console.log(JSON.stringify({ scenario: 'missing', error, fileUnchanged: readFileSync(path, 'utf8') === before }));
NODE
node --input-type=module - \""'$review_dir" <<'"'NODE'
import { join } from 'node:path';
import { loadCatalog } from './catalog/src/catalog.mjs';
const root = process.argv[2];
for (const scenario of ['pin', 'unpin']) {
  const cards = loadCatalog(join(root, scenario + '.json'));
  console.log(JSON.stringify({ scenario, reloaded: cards }));
}
NODE"

